INSERT INTO private.org_recovery(reason,payload) SELECT 'Before canonical backfill',jsonb_build_object('base',(SELECT to_jsonb(s) FROM base_org_state s WHERE id),'systems',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_systems x),'departments',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_departments x),'teams',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_teams x),'positions',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_positions x),'appointments',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_appointments x),'members',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_department_members x),'team_members',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_team_members x),'affiliations',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_member_affiliations x),'legacy_managers',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_management_assignments x),'parent_history',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM biz_department_system_history x),'user_roles',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM user_roles x));
INSERT INTO private.org_control(id) SELECT true;
INSERT INTO org_units(id,kind,name,source,source_id) SELECT 'org-company','company','Công ty cổ phần Sứ Việt','structural','company' UNION ALL SELECT 'biz-block','block','Khối Kinh doanh','structural','business';
INSERT INTO org_units(id,parent_id,kind,name,active,source,source_id,data) SELECT x->>'id',nullif(x->>'parent_id',''),x->>'kind',x->>'name',coalesce((x->>'active')::boolean,false),'base',x->>'id',x FROM base_org_state s CROSS JOIN LATERAL jsonb_array_elements(s.config->'units') x;
INSERT INTO org_units(id,parent_id,kind,name,active,source,source_id,data) SELECT id::text,'biz-block','system',name,active,'biz_systems',id::text,to_jsonb(x) FROM biz_systems x;
INSERT INTO org_units(id,parent_id,kind,name,active,source,source_id,data) SELECT id::text,system_id::text,'department',name,active,'biz_departments',id::text,to_jsonb(x) FROM biz_departments x;
INSERT INTO org_units(id,parent_id,kind,name,active,source,source_id,data) SELECT id::text,department_id::text,'team',name,active,'biz_teams',id::text,to_jsonb(x) FROM biz_teams x;
INSERT INTO org_titles(id,unit_id,name,code,level,kind,capacity,active,source,source_id,data) SELECT x->>'id',nullif(x->>'unit_id',''),x->>'name',x->>'code',coalesce((x->>'level')::int,0),coalesce(x->>'kind','staff'),coalesce((x->>'capacity')::int,0),coalesce((x->>'active')::boolean,false),'base',x->>'id',x FROM base_org_state s CROSS JOIN LATERAL jsonb_array_elements(s.config->'titles') x;
INSERT INTO org_titles(id,unit_id,name,code,level,kind,capacity,active,source,source_id,data) SELECT id::text,CASE WHEN all_business THEN 'org-company' END,name,code,level,CASE WHEN business_policy='personal' THEN 'staff' ELSE 'manager' END,CASE WHEN unit_kind='individual' THEN 0 ELSE 1 END,active,'biz_positions',id::text,to_jsonb(x) FROM biz_positions x;
INSERT INTO org_assignments(id,unit_id,title_id,user_id,category,starts_at,ends_at,status,source,source_id,data) SELECT x->>'id',x->>'unit_id',nullif(x->>'title_id',''),(x->>'user_id')::uuid,coalesce(x->>'kind','unclassified'),nullif(x->>'starts_at','')::timestamptz,nullif(x->>'ends_at','')::timestamptz,CASE WHEN (x->>'active')::boolean THEN 'active' ELSE 'ended' END,'base',x->>'id',x FROM base_org_state s CROSS JOIN LATERAL jsonb_array_elements(s.config->'memberships') x;
INSERT INTO org_assignments(id,unit_id,user_id,category,starts_at,ends_at,source,source_id,data) SELECT id::text,department_id::text,user_id,'primary',started_at,ended_at,'biz_department_members',id::text,to_jsonb(x) FROM biz_department_members x;
INSERT INTO org_assignments(id,unit_id,user_id,category,starts_at,ends_at,source,source_id,data) SELECT id::text,team_id::text,user_id,'team',started_at,ended_at,'biz_team_members',id::text,to_jsonb(x) FROM biz_team_members x;
INSERT INTO org_assignments(id,unit_id,title_id,user_id,category,starts_at,ends_at,status,source,source_id,data) SELECT a.id::text,CASE WHEN p.all_business THEN 'org-company' ELSE coalesce(a.team_id,a.department_id,a.system_id)::text END,a.position_id::text,a.user_id,'appointment',a.started_at,a.ended_at,a.status,'biz_appointments',a.id::text,to_jsonb(a) FROM biz_appointments a JOIN biz_positions p ON p.id=a.position_id;
INSERT INTO org_assignments(id,unit_id,user_id,category,starts_at,ends_at,source,source_id,data) SELECT id::text,coalesce(team_id,department_id)::text,user_id,'concurrent',started_at,ended_at,'biz_member_affiliations',id::text,to_jsonb(x) FROM biz_member_affiliations x;
INSERT INTO org_assignments(id,unit_id,user_id,category,starts_at,ends_at,source,source_id,data) SELECT id::text,coalesce(team_id,department_id,system_id)::text,user_id,'legacy_manager',started_at,ended_at,'biz_management_assignments',id::text,to_jsonb(x) FROM biz_management_assignments x;
INSERT INTO org_parent_history(id,unit_id,parent_id,starts_at,ends_at,source,data) SELECT id::text,department_id::text,system_id::text,started_at,ended_at,'biz_department_system_history',to_jsonb(x) FROM biz_department_system_history x;
