CREATE TABLE public.org_units(id text PRIMARY KEY,parent_id text,kind text NOT NULL CHECK(kind IN ('company','block','system','department','team')),name text NOT NULL,active boolean NOT NULL DEFAULT true,source text NOT NULL,source_id text NOT NULL,data jsonb NOT NULL DEFAULT '{}',revision bigint NOT NULL DEFAULT 1,UNIQUE(source,source_id)); GRANT SELECT ON public.org_units TO authenticated; GRANT ALL ON public.org_units TO service_role; ALTER TABLE public.org_units ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_titles(id text PRIMARY KEY,unit_id text REFERENCES public.org_units(id),name text NOT NULL,code text,level int NOT NULL DEFAULT 0,kind text NOT NULL CHECK(kind IN ('manager','staff')),capacity int NOT NULL DEFAULT 0 CHECK(capacity>=0),active boolean NOT NULL DEFAULT true,source text NOT NULL,source_id text NOT NULL,data jsonb NOT NULL DEFAULT '{}',revision bigint NOT NULL DEFAULT 1,UNIQUE(source,source_id)); GRANT SELECT ON public.org_titles TO authenticated; GRANT ALL ON public.org_titles TO service_role; ALTER TABLE public.org_titles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_assignments(id text PRIMARY KEY,unit_id text NOT NULL REFERENCES public.org_units(id),title_id text REFERENCES public.org_titles(id),user_id uuid NOT NULL REFERENCES public.profiles(id),category text NOT NULL CHECK(category IN ('primary','concurrent','appointment','team','legacy_manager','unclassified')),starts_at timestamptz,ends_at timestamptz,status text NOT NULL DEFAULT 'active',source text NOT NULL,source_id text NOT NULL,data jsonb NOT NULL DEFAULT '{}',revision bigint NOT NULL DEFAULT 1,UNIQUE(source,source_id)); GRANT SELECT ON public.org_assignments TO authenticated; GRANT ALL ON public.org_assignments TO service_role; ALTER TABLE public.org_assignments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_parent_history(id text PRIMARY KEY,unit_id text NOT NULL REFERENCES public.org_units(id),parent_id text,starts_at timestamptz,ends_at timestamptz,source text NOT NULL,data jsonb NOT NULL DEFAULT '{}'); GRANT SELECT ON public.org_parent_history TO authenticated; GRANT ALL ON public.org_parent_history TO service_role; ALTER TABLE public.org_parent_history ENABLE ROW LEVEL SECURITY;
CREATE TABLE private.org_control(id boolean PRIMARY KEY DEFAULT true CHECK(id),revision bigint NOT NULL DEFAULT 1);
CREATE TABLE private.org_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES public.profiles(id),revision bigint NOT NULL,baseline text NOT NULL,changes jsonb NOT NULL,impact jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes',next_transition_at timestamptz,applied_at timestamptz);
CREATE TABLE private.org_execution(transaction_id bigint PRIMARY KEY,actor_id uuid NOT NULL,preview_id uuid NOT NULL,permission text,unit_ids jsonb NOT NULL DEFAULT '[]');
CREATE TABLE private.org_recovery(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),reason text NOT NULL,payload jsonb NOT NULL);
CREATE TABLE public.org_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES public.profiles(id),before_revision bigint NOT NULL,after_revision bigint NOT NULL,unit_ids jsonb NOT NULL,reason text NOT NULL,before_data jsonb NOT NULL,after_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.org_events TO authenticated; GRANT ALL ON public.org_events TO service_role; ALTER TABLE public.org_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.org_control,private.org_previews,private.org_execution,private.org_recovery FROM PUBLIC,anon,authenticated;
COMMENT ON TABLE org_assignments IS 'Typed canonical facts preserve source identifiers and exact history; primary duties, appointments and secondary affiliations are never flattened.';
COMMENT ON TABLE private.org_recovery IS 'Private recovery snapshots before conversion; never automatically rewrite Roles, ownership or approval snapshots.';